module uart_rx #(parameter integer CLKS_PER_BIT=4)(input wire clk,input wire rst,input wire rx,output reg[7:0]data_out,output reg data_valid,output reg framing_error,output reg busy);
 localparam integer HALF_CLKS=CLKS_PER_BIT/2; localparam[1:0]IDLE=0,START=1,DATA=2,STOP=3; reg[1:0]state;reg[$clog2(CLKS_PER_BIT+1)-1:0]count;reg[2:0]bit_index;reg[7:0]shift;
 always@(posedge clk)if(rst)begin state<=IDLE;count<=0;bit_index<=0;shift<=0;data_out<=0;data_valid<=0;framing_error<=0;busy<=0;end else begin data_valid<=0;framing_error<=0;case(state)IDLE:begin busy<=0;if(!rx)begin state<=START;busy<=1;count<=0;end end START:if(count==HALF_CLKS-1)begin count<=0;if(!rx)begin state<=DATA;bit_index<=0;end else begin state<=IDLE;busy<=0;end end else count<=count+1; DATA:if(count==CLKS_PER_BIT-1)begin count<=0;shift[bit_index]<=rx;if(bit_index==7)state<=STOP;else bit_index<=bit_index+1;end else count<=count+1; STOP:if(count==CLKS_PER_BIT-1)begin data_out<=shift;data_valid<=1;framing_error<=0;state<=IDLE;busy<=0;end else count<=count+1;endcase end
endmodule
